const pineconeCreds = await this.getCredentials('pineconeApi');
const openAiCreds = await this.getCredentials('openAiApi');
const PINECONE_KEY = pineconeCreds.apiKey;
const OPENAI_KEY = openAiCreds.apiKey;

// Fetch updated Google Doc
const docText = await this.helpers.httpRequest({
  method: 'GET',
  url: 'https://docs.google.com/document/d/1TCQis3T6FIMp5vcNnPLSCxoggsPrd0EkRiMa84yYbnw/export?format=txt'
});

// Get Pinecone index host
const indexInfo = await this.helpers.httpRequest({
  method: 'GET',
  url: 'https://api.pinecone.io/indexes/atencionce',
  headers: { 'Api-Key': PINECONE_KEY, 'Accept': 'application/json' }
});
const PINECONE_HOST = 'https://' + indexInfo.host;

// Split into chunks
const chunkSize = 500, overlap = 50;
const chunks = [];
for (let i = 0; i < docText.length; i += (chunkSize - overlap)) {
  const chunk = docText.slice(i, i + chunkSize).trim();
  if (chunk) chunks.push(chunk);
  if (i + chunkSize >= docText.length) break;
}

// Embed chunks
const allVectors = [];
for (let i = 0; i < chunks.length; i += 100) {
  const batch = chunks.slice(i, i + 100);
  const embRes = await this.helpers.httpRequest({
    method: 'POST',
    url: 'https://api.openai.com/v1/embeddings',
    headers: { 'Authorization': `Bearer ${OPENAI_KEY}`, 'Content-Type': 'application/json' },
    body: { model: 'text-embedding-ada-002', input: batch }
  });
  for (let j = 0; j < batch.length; j++) {
    allVectors.push({
      id: `chunk-${i + j}`,
      values: embRes.data[j].embedding,
      metadata: { text: batch[j] }
    });
  }
}

// Clear and upsert
await this.helpers.httpRequest({
  method: 'POST',
  url: `${PINECONE_HOST}/vectors/delete`,
  headers: { 'Api-Key': PINECONE_KEY, 'Content-Type': 'application/json' },
  body: { deleteAll: true, namespace: '' }
});

for (let i = 0; i < allVectors.length; i += 100) {
  await this.helpers.httpRequest({
    method: 'POST',
    url: `${PINECONE_HOST}/vectors/upsert`,
    headers: { 'Api-Key': PINECONE_KEY, 'Content-Type': 'application/json' },
    body: { vectors: allVectors.slice(i, i + 100), namespace: '' }
  });
}

return [{ json: { status: 'ok', chunks: allVectors.length, updated: new Date().toISOString() } }];
